'use strict';

// A library that exports class instances to be consumed structurally.
// Simulates rxjs-like patterns: class instances whose public API can be
// described by structural record types.

class Subscription {
  constructor() {
    this.closed = false;
  }
  unsubscribe() {
    this.closed = true;
  }
}

class Observable {
  constructor(subscribeFn) {
    this._subscribeFn = subscribeFn;
  }
  subscribe(observer) {
    const sub = new Subscription();
    this._subscribeFn({
      next: (v) => observer.next(v),
      complete: () => {
        observer.complete();
        sub.closed = true;
      },
    });
    return sub;
  }
}

function of(...values) {
  return new Observable((sink) => {
    for (const v of values) sink.next(v);
    sink.complete();
  });
}

module.exports = { Observable, Subscription, of };
